SELECT 
FROM join_requests r JOIN users u ON u.id = r.user_id
WHERE r.community_id = #{communityId} AND r.id = #{id}

SELECT m.user_id, u.nickname, m.role, m.joined_at
FROM memberships m JOIN users u ON u.id = m.user_id
WHERE m.community_id = #{communityId}

ORDER BY CASE m.role WHEN 'owner' THEN 0 WHEN 'staff' THEN 1 ELSE 2 END, m.joined_at, m.user_id
LIMIT #{limit} OFFSET #{offset}

SELECT m.user_id, u.nickname, m.role, m.joined_at
FROM memberships m JOIN users u ON u.id = m.user_id
WHERE m.community_id = #{communityId} AND m.user_id = #{userId}
